UPDATE t_stock_info
SET stock_name = #{stockName}, exchange = #{exchange}, industry = #{industry},
    current_price = #{currentPrice}, open_price = #{openPrice}, high_price = #{highPrice},
    low_price = #{lowPrice}, pre_close = #{preClose}, volume = #{volume},
    amount = #{amount}, update_time = #{updateTime}
WHERE stock_code = #{stockCode}
